using System;using System.IO;using System.Linq;using System.Collections.Generic;using EchoSphere.Core;public static class FormationRecognitionCheck {public static object Main(){var cases=new Dictionary<SphereNetworkFormation,Vec2[]>();Vec2[] Ring(int n,float r)=>Enumerable.Range(0,n).Select(i=>new Vec2((float)Math.Cos(i*2*Math.PI/n)*r,(float)Math.Sin(i*2*Math.PI/n)*r)).ToArray();cases[SphereNetworkFormation.Line]=new[]{new Vec2(-100,0),new Vec2(0,0),new Vec2(100,0)};cases[SphereNetworkFormation.Triangle]=Ring(3,85);cases[SphereNetworkFormation.Square]=new[]{new Vec2(-70,-70),new Vec2(70,-70),new Vec2(70,70),new Vec2(-70,70)};cases[SphereNetworkFormation.Ring]=Ring(5,110);cases[SphereNetworkFormation.Lattice]=new[]{new Vec2(0,0),new Vec2(120,0),new Vec2(60,103.923f),new Vec2(180,103.923f)};cases[SphereNetworkFormation.Fractal]=Ring(6,100);var results=new List<object>();int probes=0;foreach(var c in cases){int found=0,primary=0;for(int step=0;step<36;step++)for(int shift=0;shift<c.Value.Length;shift++){double angle=step*Math.PI/18;var nodes=Enumerable.Range(0,c.Value.Length).Select(i=>{var p=c.Value[(i+shift)%c.Value.Length];return new SphereNetworkNode(new Vec2((float)(p.X*Math.Cos(angle)-p.Y*Math.Sin(angle))*SpherePlacementRules.SourcePixelsToWorld,(float)(p.X*Math.Sin(angle)+p.Y*Math.Cos(angle))*SpherePlacementRules.SourcePixelsToWorld));}).ToArray();var state=SphereNetworkRules.Analyze(nodes);if(state.FormationCandidates.Any(f=>f.Type==c.Key))found++;if(state.DominantFormation?.Type==c.Key)primary++;probes++;}results.Add(new{shape=c.Key.ToString(),recognized=found,primary,total=36*c.Value.Length});}var report=new{status="AUDIT",probes,results,scope="read-only rotations and index permutations, actual recognition and primary ranking; no threshold changes"};Directory.CreateDirectory("Library/archive-illustrations");File.WriteAllText("Library/archive-illustrations/formation-recognition.json",Newtonsoft.Json.JsonConvert.SerializeObject(report));return report;}}